// (cmSpec) uses the wider isAsciiPunct instead (see isEscapable). File-level const; it is only
// tested (no lastIndex state), so reuse across invocations is safe.
const reShowdownEscapable = /[!#%'()*+,\-./:;=?@[\]\\^_`{|}~]/;

